css:
/* ===================================================================
   Copperplate Engine  (steampunk starter)  by kolache
   One idea: everything you read is a printed card, and brass is only
   ever the hardware that holds it: one rail down the reading column,
   spring clips, card-catalogue label holders, corner brackets, a
   typewriter platen. Pictures are hand-tinted copperplate engravings.
   =================================================================== */

:root {
  --mari-tokens-version: 1;

  /* type */
  --mari-font-ui: "Libre Caslon Text", Georgia, serif;
  --cp-typed: "Courier Prime", "Courier New", monospace;
  --mari-font-heading: "Old Standard TT", "Libre Caslon Text", Georgia, serif;
  --mari-font-chat: "Libre Caslon Text", Georgia, serif;
  --mari-chat-font-size: 1rem;
  --mari-chat-line-height: 1.68;
  --mari-message-measure: 66ch;
  --mari-dialogue-weight: 400;
  --mari-paragraph-gap: 0.8em;
  --mari-text-outline: 0;
  --mari-min-ui-text: 12px;
  --mari-composer-placeholder: "feed a card...";
  --mari-pinned-speaker: on;

  /* palette (shared) */
  --cp-brass: #c9a04a;
  --cp-brass-hi: #f0d58a;
  --cp-brass-lo: #6e4f1c;
  --cp-copper: #b8693d;
  --cp-verdigris: #3d7d70;
  --cp-iron: #26354a;
  --cp-oxblood: #8e2b22;
  --cp-brass-rod: linear-gradient(90deg, #5c4016, #c9a04a 25%, #f6de96 42%, #c9a04a 60%, #543a14);
  --cp-brass-bar: linear-gradient(180deg, #f6de96, #c9a04a 35%, #8a6526 80%, #5c4016);

  --radius: 0.2rem;
  --mari-selected-tint: var(--cp-brass);
  --mari-chat-column: 56rem;
  --mari-phone-avatar: hidden;

  /* frames */
  --mari-focus-frame: url("theme:brackets.png") 32 / 32px / 0 stretch;
  --mari-focus-frame-outset: 7px;

  /* home */
  --mari-home-widget-radius: 0.15rem;
  --mari-home-widget-border-width: 1px;
  --mari-home-widget-font: var(--mari-font-ui);
  --mari-home-widget-title-font: var(--mari-font-heading);
  --mari-home-widget-title-size: 1.6rem;
  --mari-home-widget-text-size: 0.88rem;
  --mari-home-widget-eyebrow-size: 0.72rem;
  --mari-home-wash: transparent;
  --mari-home-widget-glow: transparent;

  /* backdrop */
  --mari-app-backdrop-size: cover;
  --mari-app-backdrop-position: center;
  --mari-chat-row-art-opacity: 0;

  /* top bar */
  --mari-top-bar-bg: url("theme:topbar-beam.webp") center / auto 100% repeat-x, #26354a;
  --mari-top-bar-plate-radius: 0.15rem;

  /* weather: the engine hall's own */
  --mari-weather-amount: 0.9;
  --mari-weather-strength: 1.5;
  --mari-weather-rain-size: 1.8;
  --mari-weather-snow-size: 2.4;
  --mari-weather-fog-size: 1.2;
  --mari-weather-tint-strength: 0.55;
  --mari-weather-rain-length: 2.4;
  --mari-weather-leaf-image: url("theme:chad-1.png") url("theme:chad-2.png") url("theme:chad-3.png");
  --mari-weather-leaf-size: 0.7;
  --mari-weather-ember-color: #f0c060;
  --mari-weather-ember-shape: square;
  --mari-weather-ash-color: #3b3530;
  --mari-weather-fog-color: #efe6d6;
  --mari-weather-lightning-color: #e6dcff;
  --mari-weather-lightning-bolt: 1.4;
  --mari-weather-sun: none;
  --mari-weather-moon: none;
}

/* ---------------- DAY: cream card stock in a skylit engine hall --------------- */
:root[data-theme="light"] {
  --background: #e9dfc8;
  --foreground: #2b2118;
  --card: #f3ead6;
  --card-foreground: #2b2118;
  --popover: #f6eedc;
  --popover-foreground: #2b2118;
  --primary: #7a5418;
  --primary-foreground: #fff8e6;
  --secondary: #e4d6b4;
  --secondary-foreground: #2b2118;
  --muted: #e6dabe;
  --muted-foreground: #5e4d36;
  --accent: #d9e6df;
  --accent-foreground: #1f3b35;
  --destructive: #8e2b22;
  --destructive-foreground: #fff4ec;
  --border: #b49a68;
  --input: #c9b68c;
  --ring: #7a5418;
  --sidebar: #e0d5ba;
  --sidebar-foreground: #2b2118;
  --sidebar-border: #b49a68;
  --sidebar-accent: #d2c39f;
  --sidebar-accent-foreground: #2b2118;
  --ov-line: #c3ad7f;
  --mari-chrome-accent: #7a5418;
  --mari-chrome-muted: #5e4d36;

  --cp-card: #f3ead6 url("theme:card-day.webp") 0 0 / 256px;
  --cp-manila: #ecdfbe url("theme:manila-day.webp") 0 0 / 256px;
  --cp-ink: #2b2118;
  --cp-ink-soft: #5a4630;
  --cp-rule: #b49a68;
  --cp-holes: url("theme:hollerith-day.png");
  --cp-card-solid: #f3ead6;
  --mari-pinned-speaker-bg: #f3ead6;
  --mari-dialogue-color: #6b2c22;
  --mari-message-time: #6e5a3c;
  --mari-message-actions: #6e5a3c;
  --mari-page-veil: rgba(243, 234, 214, 0.9);
  --mari-scrim: rgba(38, 53, 74, 0.55);
  --mari-app-backdrop: url("theme:backdrop-day.webp");
  --mari-chat-wash: linear-gradient(rgba(214, 196, 158, 0.3), rgba(214, 196, 158, 0.3));
  --mari-app-backdrop-layers: url("theme:backdrop-day.webp") center / cover no-repeat, var(--background);
  --mari-top-bar-plate: rgba(243, 234, 214, 0.94);
  --mari-top-bar-plate-active: #f0d58a;
  --mari-home-widget-bg: var(--cp-card);
  --mari-home-widget-border: #b49a68;
  --mari-home-widget-title-color: #2b2118;
  --mari-home-widget-eyebrow-color: #7b2a1f;
  --mari-home-widget-muted: #5a4630;
  --mari-weather-rain-color: #f2f7f4;
  --mari-weather-snow-color: #ffffff;
  --mari-weather-dust-color: #b08a3c;
}

/* ---------------- NIGHT: the same card stock, dimmed and lit by gaslight --------------- */
:root[data-theme="dark"] {
  --background: #121a28;
  --foreground: #efe4cc;
  --card: #1b2433;
  --card-foreground: #efe4cc;
  --popover: #1d2737;
  --popover-foreground: #efe4cc;
  --primary: #e3b45c;
  --primary-foreground: #1a1206;
  --secondary: #263246;
  --secondary-foreground: #efe4cc;
  --muted: #222c3d;
  --muted-foreground: #c2b391;
  --accent: #23403b;
  --accent-foreground: #d7efe8;
  --destructive: #c4513f;
  --destructive-foreground: #fff4ec;
  --border: #4a4a3c;
  --input: #3a4153;
  --ring: #e3b45c;
  --sidebar: #0e1522;
  --sidebar-foreground: #efe4cc;
  --sidebar-border: #05080f;
  --sidebar-accent: #1c2738;
  --sidebar-accent-foreground: #fff6df;
  --ov-line: #3d4658;
  --mari-chrome-accent: #e3b45c;
  --mari-chrome-muted: #c2b391;

  --cp-card: radial-gradient(120% 90% at 85% 0%, rgba(255, 196, 110, 0.16), transparent 60%), #cdbd98 url("theme:card-night.webp") 0 0 / 256px;
  --cp-card-solid: #cdbd98;
  --cp-manila: radial-gradient(120% 90% at 15% 0%, rgba(255, 196, 110, 0.14), transparent 60%), #bfad84 url("theme:manila-night.webp") 0 0 / 256px;
  --cp-ink: #22180e;
  --cp-ink-soft: #4a3a24;
  --cp-rule: #7d6638;
  --cp-holes: url("theme:hollerith-night.png");
  --mari-pinned-speaker-bg: #cdbd98;
  --mari-dialogue-color: #5e2318;
  --mari-message-time: #4f3f28;
  --mari-message-actions: #c9b993;
  --mari-page-veil: rgba(18, 26, 40, 0.9);
  --mari-scrim: rgba(5, 8, 15, 0.66);
  --mari-app-backdrop: url("theme:backdrop-night.webp");
  --mari-chat-wash: linear-gradient(rgba(14, 21, 34, 0.4), rgba(14, 21, 34, 0.4));
  --mari-app-backdrop-layers: url("theme:backdrop-night.webp") center / cover no-repeat, var(--background);
  --mari-top-bar-plate: rgba(8, 12, 20, 0.7);
  --mari-top-bar-plate-active: #6b4f1d;
  --mari-home-widget-bg: var(--cp-card);
  --mari-home-widget-border: #7d6638;
  --mari-home-widget-title-color: #22180e;
  --mari-home-widget-eyebrow-color: #5a2a18;
  --mari-home-widget-muted: #4a3a24;
  --mari-weather-rain-color: #c4e2da;
  --mari-weather-snow-color: #f3ead6;
  --mari-weather-star-color: #f0d58a;
  --mari-weather-firefly-color: #f0c060;
  --mari-weather-dust-color: #e3b45c;
}

/* weather-aware backdrops */
:root[data-theme="light"][data-mari-weather="rain"],
:root[data-theme="light"][data-mari-weather="storm"],
:root[data-theme="light"][data-mari-weather="fog"] {
  --mari-app-backdrop: url("theme:backdrop-rain.webp");
  --mari-app-backdrop-layers: url("theme:backdrop-rain.webp") center / cover no-repeat, var(--background);
}
:root[data-theme="light"][data-mari-weather="snow"],
:root[data-theme="light"][data-mari-weather="hail"] {
  --mari-app-backdrop: url("theme:backdrop-snow.webp");
  --mari-app-backdrop-layers: linear-gradient(rgba(58, 78, 98, 0.32), rgba(58, 78, 98, 0.32)), url("theme:backdrop-snow.webp") center / cover no-repeat, var(--background);
}

/* ===================== THE RAIL AND THE CARDS (roleplay) ===================== */

/* the rail: one riveted brass rod down the reading column, left of every card */
[data-chat-mode="roleplay"] .mari-roleplay-message-body::before {
  content: "";
  position: absolute;
  left: -14px;
  top: -0.6rem;
  bottom: -2.4rem;
  width: 16px;
  background: url("theme:rail.png") center top / 16px 96px repeat-y;
  filter: drop-shadow(1px 0 1px rgba(0, 0, 0, 0.35));
  pointer-events: none;
  z-index: 0;
}
/* the rail is fixed to the wall at the top and ends in a turned brass finial */
.mari-messages-scroll > div:has(> .mari-roleplay-message-row):not(:has(~ div > .mari-roleplay-message-row)) .mari-roleplay-message-body::before {
  bottom: -1.4rem;
  background:
    url("theme:rail-end.png") center bottom / 20px 28px no-repeat,
    url("theme:rail.png") center top / 16px 96px repeat-y;
  background-clip: border-box;
  -webkit-mask: linear-gradient(#000, #000) center top / 8px calc(100% - 24px) no-repeat, linear-gradient(#000, #000) center bottom / 100% 28px no-repeat;
  mask: linear-gradient(#000, #000) center top / 8px calc(100% - 24px) no-repeat, linear-gradient(#000, #000) center bottom / 100% 28px no-repeat;
}
.mari-messages-scroll > div:has(> .mari-roleplay-message-row):not(div:has(> .mari-roleplay-message-row) ~ div) .mari-roleplay-message-body::before {
  top: -1.6rem;
  background:
    url("theme:rail-top.png") center top / 36px 46px no-repeat,
    url("theme:rail.png") center 44px / 16px 96px repeat-y;
  width: 36px;
  left: -24px;
}

/* output cards (character replies) */
[data-chat-mode="roleplay"] .mari-rp-bubble:not(.mari-rp-bubble--user) {
  background: var(--cp-card);
  color: var(--cp-ink);
  border: 1px solid var(--cp-rule);
  border-radius: 1px;
  box-shadow:
    inset 0 0 0 4px transparent,
    inset 0 0 0 5px color-mix(in srgb, var(--cp-rule) 55%, transparent),
    0 2px 0 rgba(0, 0, 0, 0.12),
    0 10px 22px -12px rgba(0, 0, 0, 0.55);
  backdrop-filter: none;
}
/* the spring clip that hangs each output card on the rail */
[data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body::after {
  content: "";
  position: absolute;
  left: -30px;
  top: -24px;
  width: 56px;
  height: 56px;
  background: url("theme:clip.png") center / contain no-repeat;
  filter: drop-shadow(1px 2px 1px rgba(0, 0, 0, 0.4));
  pointer-events: none;
  z-index: 2;
}

/* input cards (your messages): manila, punched down the left margin */
[data-chat-mode="roleplay"] .mari-rp-bubble--user {
  background:
    var(--cp-holes) 4px 0 / 34px 80px repeat-y,
    linear-gradient(var(--cp-rule), var(--cp-rule)) 42px 0 / 1px 100% no-repeat,
    var(--cp-manila);
  background-repeat: no-repeat round, no-repeat, repeat;
  background-origin: padding-box, border-box, border-box;
  background-clip: border-box;
  color: var(--cp-ink);
  border: 1px solid var(--cp-rule);
  border-radius: 0;
  padding: 6px 0 6px 34px;
  clip-path: polygon(14px 0, 100% 0, 100% 100%, 0 100%, 0 14px);
}
[data-chat-mode="roleplay"] .mari-rp-bubble--user::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 20px;
  height: 20px;
  background: linear-gradient(135deg, transparent 9px, var(--cp-rule) 9px 10px, transparent 10px);
  pointer-events: none;
}

/* the speaker's name sits in a brass label holder */
[data-chat-mode="roleplay"] [data-mari-part="header"] {
  --mari-msg-head-rule: none;
  border-bottom: 1px solid color-mix(in srgb, var(--cp-rule) 60%, transparent);
  padding-bottom: 0.45rem;
  margin-bottom: 0.7rem;
}
/* while the plate is pinned over a long reply, a band of card stock fades the line beneath it out */
:root[data-mari-pinned-speaker] [data-chat-mode="roleplay"] .mari-rp-bubble .ov-rpmsg__head {
  padding-top: 0.55rem;
  background: var(--cp-card-solid);
  box-shadow: 0 0.95rem 0.6rem -0.35rem var(--cp-card-solid);
}
[data-chat-mode="roleplay"] [data-mari-part="header"] .mari-message-name {
  display: inline-block;
  padding: 0 0.35rem;
  line-height: 1.25;
  border-style: solid;
  border-width: 5px 14px;
  border-image: url("theme:label-holder.png") 9 28 10 28 fill / 5px 14px stretch;
  background: none;
  color: #2b2118;
  font-family: var(--mari-font-heading);
  font-variant: small-caps;
  letter-spacing: 0.06em;
  font-size: 0.95rem;
  text-shadow: none;
}
:root[data-theme="light"] [data-chat-mode="roleplay"] [data-mari-part="header"] .mari-message-name {
  color: #2b2118;
}
[data-chat-mode="roleplay"] .mari-message-content {
  font-family: var(--mari-font-chat);
  color: var(--cp-ink);
}

/* avatars: cabinet-card portraits on a cream mount */
[data-chat-mode="roleplay"] [data-mari-part="avatar"] button,
[data-chat-mode="roleplay"] [data-mari-part="avatar"] img {
  border-radius: 1px !important;
}
[data-chat-mode="roleplay"] [data-mari-part="avatar"] button {
  box-shadow: 0 0 0 3px #efe4cc, 0 0 0 4px var(--cp-brass-lo), 0 6px 10px -4px rgba(0, 0, 0, 0.6);
}
[data-chat-mode="roleplay"] .rpg-avatar-glow {
  filter: none;
  box-shadow: none;
}

/* scene break */
[data-chat-mode="roleplay"] .mari-message-content hr {
  border: 0;
  height: 10px;
  margin: 1.2em auto;
  width: 40%;
  background:
    radial-gradient(circle, var(--cp-brass) 0 3px, transparent 3.5px) center / 10px 10px no-repeat,
    linear-gradient(var(--cp-rule), var(--cp-rule)) center / 100% 1px no-repeat;
}

/* ======================= COMPOSER: a typewriter carriage ====================== */
[data-mari-part="composer"] .mari-chat-input-box {
  position: relative;
  background: var(--cp-card);
  color: var(--cp-ink);
  border: 1px solid var(--cp-rule);
  border-radius: 1px;
  margin-top: 8px;
  padding-top: 6px;
  box-shadow: 0 10px 24px -14px rgba(0, 0, 0, 0.7);
}
/* the platen roller with its two brass knobs, laid across the top edge */
[data-mari-part="composer"] .mari-chat-input-box::before {
  content: "";
  position: absolute;
  left: -10px;
  right: -10px;
  top: -10px;
  height: 18px;
  border-radius: 3px;
  background:
    repeating-linear-gradient(90deg, rgba(60, 40, 12, 0.55) 0 1px, transparent 1px 3px) left center / 16px 18px no-repeat,
    repeating-linear-gradient(90deg, rgba(60, 40, 12, 0.55) 0 1px, transparent 1px 3px) right center / 16px 18px no-repeat,
    linear-gradient(180deg, #f6de96, #c9a04a 40%, #6e4f1c) left center / 16px 18px no-repeat,
    linear-gradient(180deg, #f6de96, #c9a04a 40%, #6e4f1c) right center / 16px 18px no-repeat,
    linear-gradient(180deg, #8d97a8 0%, #3b4452 22%, #161b23 55%, #0b0e13 75%, #343c4a 100%) center / calc(100% - 28px) 14px no-repeat;
  pointer-events: none;
}
/* an iron carriage bed under the sheet, so nothing of the reply shows past the typewriter */
[data-mari-part="composer"] {
  background: linear-gradient(180deg, transparent 0, #1d232d 4px, #12161d);
  box-shadow: 0 -1px 0 #8a6526;
  padding-top: 14px;
}
@media (max-width: 767px) {
  [data-mari-part="composer"] .mari-chat-input-box,
  [data-mari-part="composer"] .mari-chat-input-box * {
    border-radius: 1px !important;
  }
}
[data-mari-part="composer"] textarea {
  font-family: var(--mari-font-chat);
  color: var(--cp-ink);
  font-size: 1rem;
  padding-top: 2px;
}
[data-mari-part="composer"] textarea::placeholder {
  color: var(--cp-ink-soft);
  font-family: var(--cp-typed);
}

/* ======================= TOP BAR: an iron girder with a brass rail ======================= */
.ov-topbar {
  border-bottom: 0;
  box-shadow: 0 3px 0 -1px #8a6526, 0 4px 10px rgba(0, 0, 0, 0.35);
}
.ov-topbar .ov-tab,
.ov-topbar .ov-text-btn,
.ov-topbar .ov-icon-btn {
  font-family: var(--cp-typed);
}
.ov-topbar .ov-tab.is-on {
  box-shadow: inset 0 -2px 0 #e3c378;
}

/* ======================= SIDEBARS: card-catalogue cabinets ======================= */
/* typed index labels */
[data-mari-part="time"],
[data-mari-part="home-widget-eyebrow"],
.ov-eyebrow,
.ov-mode-count {
  font-family: var(--cp-typed);
}
[data-chat-row] {
  border-radius: 1px;
  margin-block: 3px;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.05), rgba(255, 255, 255, 0.12));
  box-shadow: inset 0 0 0 1px rgba(138, 101, 38, 0.55), inset 0 2px 4px rgba(60, 40, 10, 0.22);
}
:root[data-theme="dark"] [data-chat-row] {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(0, 0, 0, 0.18));
  box-shadow: inset 0 0 0 1px rgba(201, 160, 74, 0.35), inset 0 2px 4px rgba(0, 0, 0, 0.4);
}
:root[data-theme] [data-chat-row][data-selected="true"] {
  background: var(--cp-card);
  box-shadow: inset 0 0 0 1px #8a6526, 0 2px 0 #5c4016;
}
:root [data-chat-row][data-selected="true"] .mari-chrome-text-strong,
:root [data-chat-row][data-selected="true"] span {
  color: var(--cp-ink);
}

/* ======================= HOME: cards in brass card holders ======================= */
[data-mari-part="home-widget"] {
  box-shadow: 0 12px 26px -16px rgba(0, 0, 0, 0.7);
  background:
    radial-gradient(circle at 12px 12px, #f6de96 0 1.5px, #c9a04a 2px 3.5px, #5c4016 4px, transparent 4.5px),
    radial-gradient(circle at calc(100% - 12px) 12px, #f6de96 0 1.5px, #c9a04a 2px 3.5px, #5c4016 4px, transparent 4.5px),
    var(--cp-card);
}
/* each widget's eyebrow is the typed label in a brass label holder */
[data-mari-part="home-widget-eyebrow"] {
  display: inline-block;
  width: fit-content;
  padding: 0.05rem 0.4rem;
  border-style: solid;
  border-width: 5px 14px;
  border-image: url("theme:label-holder.png") 9 28 10 28 fill / 5px 14px stretch;
  color: #5a2a18 !important;
  letter-spacing: 0.14em;
}
[data-mari-part="home-widget-title"] {
  font-variant: small-caps;
  letter-spacing: 0.04em;
}

/* the stock chat background steps aside for the engraving */
img[data-mari-part="backdrop"][data-default-background] {
  opacity: 0 !important;
}

/* ============ CONVERSATION: one continuous punched tape, sprocket holes both edges ============ */
[data-chat-mode="conversation"] .mari-messages-scroll > * {
  width: min(100% - 2rem, 60rem);
  margin-inline: auto;
  padding-inline: 1.6rem;
  background:
    var(--cp-holes) left 2px top 0 / 20px 26px repeat-y,
    var(--cp-holes) right 2px top 0 / 20px 26px repeat-y,
    var(--cp-card);
  border-inline: 1px solid var(--cp-rule);
  color: var(--cp-ink);
}
[data-chat-mode="conversation"] .mari-messages-scroll > *:first-child {
  margin-top: 1.25rem;
  border-top: 1px solid var(--cp-rule);
}
[data-chat-mode="conversation"] .mari-messages-scroll > *:last-child {
  border-bottom: 1px solid var(--cp-rule);
  margin-bottom: 1.25rem;
}
[data-chat-mode="conversation"] .mari-message-name {
  font-family: var(--mari-font-heading);
  font-variant: small-caps;
  letter-spacing: 0.04em;
}
[data-chat-mode="conversation"] .mari-message-content {
  font-family: var(--mari-font-chat);
  color: var(--cp-ink);
}
[data-chat-mode="conversation"] [data-mari-part="avatar"] button {
  border-radius: 1px !important;
  box-shadow: 0 0 0 2px #efe4cc, 0 0 0 3px var(--cp-brass-lo);
}

/* ============ GAME: the narration is an output card on a card-reader bar ============ */
