  letter-spacing: 0.14em;
}
[data-game-narration] .mari-game-meta,
[data-game-narration] button {
  border-radius: 1px;
}
[data-mari-part="game-hud"] > * {
  border-radius: 1px;
}
:root {
  --mari-stage-empty-bg: url("theme:stage-empty.webp") left 30% center / cover, #2a2a26;
}

/* ============ DIALOGS, POPOVERS, CTRL+K: big cards with brass corner brackets ============ */
[role="dialog"],
[data-component="GlobalOmnibar"] > div,
.mari-window {
  border-radius: 2px !important;
}
[role="dialog"] {
  background: var(--cp-card);
}
[data-mari-part="home-widget-title"] {
