}
[data-mari-part="home-widget"] > header [data-mari-part="home-widget-eyebrow"] {
  position: absolute;
  top: -1.95rem;
  left: 0;
  line-height: 1.1;
  white-space: nowrap;
}

/* ============ LIBRARY: every card picture is a cabinet card on a cream mount ============ */
:root {
  --mari-art-saturation-1: 22%;
  --mari-art-lightness-1: 62%;
  --mari-art-saturation-2: 26%;
  --mari-art-lightness-2: 38%;
}
[data-mari-part="card-art"] {
