}

/* phones and portrait tablets get the tall engraving */
@media (max-aspect-ratio: 4/5) {
  :root[data-theme="light"] { --mari-app-backdrop: url("theme:phone-day.webp"); --mari-app-backdrop-layers: url("theme:phone-day.webp") center / cover no-repeat, var(--background); }
  :root[data-theme="dark"] { --mari-app-backdrop: url("theme:phone-night.webp"); --mari-app-backdrop-layers: url("theme:phone-night.webp") center / cover no-repeat, var(--background); }
