}

/* ============ SIDE PANELS & POPOVERS: card stock with a brass edge ============ */
[data-component="RightPanelDesktop"] {
  box-shadow: inset 3px 0 0 -1px rgba(138, 101, 38, 0.6);
}
[data-component="ChatSidebar"] {
  box-shadow: inset -3px 0 0 -1px rgba(138, 101, 38, 0.6);
}

[data-mari-part="header"][data-placement="outside"] {
  border-radius: 1px !important;
}

/* =====================================================================
   ROUND 2
   ===================================================================== */

/* the band of card stock under a pinned name plate fades the line beneath it out completely */
:root[data-mari-pinned-speaker] [data-chat-mode="roleplay"] .mari-rp-bubble .ov-rpmsg__head::after {
  content: "";
  position: absolute;
