  box-shadow: none;
}

/* composer tools in ink, on the sheet */
[data-mari-part="composer"] .mari-chat-input-box button {
  color: var(--cp-ink-soft);
}
[data-mari-part="composer"] .mari-chat-send-btn {
  color: var(--cp-ink);
}
@media (max-width: 1279px) {
  [data-mari-part="composer"] .mari-chat-input-box::before {
    left: 0;
    right: 0;
