/* ---------- phone: the name plate sits on the card, one card per message ---------- */
[data-chat-mode="roleplay"] .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
  background: var(--cp-card-solid);
  border: 1px solid var(--cp-rule);
