}
.mari-message-user .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
  background: #ecdfbe;
}
:root[data-theme="dark"] .mari-message-user .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
  background: #bfad84;
}
.mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) > .mari-rp-bubble {
  border-top: 0 !important;
  clip-path: none !important;
}
.mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) > .mari-rp-bubble::before {
  display: none;
}
@media (max-width: 767px) {
  [data-chat-mode="roleplay"] .mari-roleplay-message-body {
    padding-left: 16px;
  }
  [data-chat-mode="roleplay"] .mari-roleplay-message-body::before {
    left: 0;
  }
  [data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body::after {
    left: -4px;
    top: -12px;
    width: 34px;
    height: 34px;
    z-index: 5;
  }
  .mari-messages-scroll > div:has(> .mari-roleplay-message-row):not(div:has(> .mari-roleplay-message-row) ~ div) .mari-roleplay-message-body::before {
    left: -6px;
  }
}

/* ---------- square riveted plates instead of pills ---------- */
.mari-chrome-control,
.ov-chip,
.ov-chip-btn,
.ov-pill,
.ov-tag,
.ov-btn,
.ov-addchip,
.ov-new-pill,
.ov-libnav__tag,
.ov-search,
.ov-select,
.ov-seg,
.ov-seg > *,
.ov-home-modes button,
[data-component="ChatSidebar"] button,
[data-component="ChatSidebar"] input,
[data-component="OverhaulLibraryPage"] button:not(:has(img)),
[data-component="OverhaulLibraryPage"] input,
[data-component="OverhaulLibraryPage"] select,
.ov-settings button:not(:has(img)),
.ov-settings select,
.ov-settings input,
.ov-gpane button,
[data-mari-part="game-tools"] button,
[data-game-narration] button {
  border-radius: 1px !important;
}
.ov-chip,
.ov-home-modes button {
  background-image:
    radial-gradient(circle at 6px 50%, #f6de96 0 1px, #a5802f 1.6px 2.4px, transparent 2.9px),
    radial-gradient(circle at calc(100% - 6px) 50%, #f6de96 0 1px, #a5802f 1.6px 2.4px, transparent 2.9px) !important;
  padding-inline: 0.95rem !important;
}
/* toggles: a square brass lever in a slot */
[data-settings-switch-track] {
  border-radius: 1px !important;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.45);
}
[data-settings-switch-thumb] {
  border-radius: 1px !important;
  background: linear-gradient(90deg, #6e4f1c, #f6de96 45%, #c9a04a 60%, #6e4f1c) !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
}
[data-settings-switch-track][data-checked] {
  background: #3d7d70 !important;
}

/* off-palette teal goes verdigris and brass */
:root {
  --mari-mode-conversation: #3d7d70;
  --mari-ctrlk-conversation: #3d7d70;
  --mari-ctrlk-roleplay: #8e5a22;
  --mari-ctrlk-game: #8e2b22;
  --mari-game-combat-bg: #8e2b22;
  --mari-game-combat-bg-hover: #a3352a;
  --mari-game-combat-border: #5e1c16;
  --mari-game-combat-text: #fff4ec;
}

/* ---------- Ctrl+K: card, no coloured wash, eyebrows in label holders ---------- */
[data-component="GlobalOmnibar.Panel"] > .pointer-events-none.absolute.-z-10 {
  display: none;
}

/* ---------- Settings: each section is a card with its title in a label holder ---------- */
.ov-settings__sections section {
  background: var(--cp-card) !important;
  border: 1px solid var(--cp-rule) !important;
  border-radius: 1px !important;
  box-shadow: 0 8px 18px -14px rgba(0, 0, 0, 0.6) !important;
  --foreground: var(--cp-ink);
  --card-foreground: var(--cp-ink);
  --muted-foreground: var(--cp-ink-soft);
  --marinara-chat-chrome-panel-title: var(--cp-ink);
  --marinara-chat-chrome-panel-muted: var(--cp-ink-soft);
  --border: var(--cp-rule);
  --secondary: color-mix(in srgb, var(--cp-card-solid) 80%, #000 6%);
  --background: var(--cp-card-solid);
  --input: var(--cp-rule);
  --accent: color-mix(in srgb, var(--cp-card-solid) 85%, #8a6526);
  --primary: #6b4a14;
  --marinara-chat-chrome-button-bg: color-mix(in srgb, var(--cp-card-solid) 82%, #8a6526);
  --marinara-chat-chrome-button-bg-hover: color-mix(in srgb, var(--cp-card-solid) 70%, #8a6526);
  --marinara-chat-chrome-button-text: var(--cp-ink);
  --marinara-chat-chrome-text: var(--cp-ink);
  --marinara-chat-chrome-button-border: var(--cp-rule);
  color: var(--cp-ink);
}
.ov-settings__sections section .mari-chrome-control {
  background: color-mix(in srgb, var(--cp-card-solid) 82%, #8a6526) !important;
  color: var(--cp-ink) !important;
  border: 1px solid var(--cp-rule) !important;
}
.ov-settings__sections section > div:first-child .font-semibold {
  display: inline-block;
  padding: 0 0.4rem;
  border-style: solid;
  border-width: 5px 14px;
  border-image: url("theme:label-holder.png") 9 28 10 28 fill / 5px 14px stretch;
  color: #2b2118 !important;
  font-family: var(--mari-font-heading);
  font-variant: small-caps;
  letter-spacing: 0.06em;
  font-size: 0.85rem;
}

/* ---------- Game: the party panel is a ledger, the map box a pinned survey card ---------- */
.ov-gpane {
  background:
    repeating-linear-gradient(180deg, transparent 0 27px, color-mix(in srgb, var(--cp-rule) 35%, transparent) 27px 28px),
    var(--cp-card) !important;
  border-left: 3px double #8a6526 !important;
  --foreground: var(--cp-ink);
  --card-foreground: var(--cp-ink);
  --muted-foreground: var(--cp-ink-soft);
  --marinara-chat-chrome-panel-title: var(--cp-ink);
  --marinara-chat-chrome-panel-muted: var(--cp-ink-soft);
  --ov-text: var(--cp-ink);
  --ov-muted: var(--cp-ink-soft);
  --ov-dim: var(--cp-ink-soft);
  --ov-line: var(--cp-rule);
  --border: var(--cp-rule);
  --secondary: color-mix(in srgb, var(--cp-card-solid) 85%, #8a6526);
  --ov-hover: color-mix(in srgb, var(--cp-card-solid) 85%, #8a6526);
  --ov-active-bg: color-mix(in srgb, var(--cp-card-solid) 80%, #8a6526);
  --primary: #6b4a14;
  --mari-chrome-accent: #6b4a14;
  color: var(--cp-ink);
}
.ov-gpane__tabs button.is-on {
  border-style: solid !important;
  border-width: 4px 10px !important;
  padding-inline: 0.2rem !important;
  border-image: url("theme:label-holder.png") 9 28 10 28 fill / 5px 14px stretch !important;
  background: none !important;
  color: #2b2118 !important;
}
[data-tour="game-map"] {
  background: var(--cp-card) !important;
  border: 1px solid var(--cp-rule) !important;
  border-radius: 1px !important;
  backdrop-filter: none !important;
  --marinara-chat-chrome-panel-muted: var(--cp-ink-soft);
  --foreground: var(--cp-ink);
  color: var(--cp-ink);
  box-shadow: 0 10px 18px -12px rgba(0, 0, 0, 0.7);
  position: relative;
}
[data-tour="game-map"]::before {
  content: "";
  position: absolute;
  top: -7px;
  left: calc(50% - 7px);
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #f6de96, #c9a04a 45%, #5c4016 80%);
  box-shadow: 0 2px 2px rgba(0, 0, 0, 0.5);
}

/* ---------- Library: no-picture cards as sepia albumen prints ---------- */
:root {
  --mari-art-saturation-1: 14%;
  --mari-art-lightness-1: 58%;
  --mari-art-saturation-2: 18%;
  --mari-art-lightness-2: 34%;
}
[data-mari-part="card-art"][data-placeholder] {
  filter: sepia(0.55) saturate(0.7) contrast(0.95);
  box-shadow: 0 0 0 1px #8a6526, inset 0 0 26px rgba(40, 24, 8, 0.55), 0 10px 18px -10px rgba(0, 0, 0, 0.6);
}

/* ---------- Conversation: an unbroken tape, composer the same width ---------- */
[data-chat-mode="conversation"] .mari-messages-scroll {
  gap: 0 !important;
  row-gap: 0 !important;
}
[data-chat-mode="conversation"] .mari-messages-scroll > * {
  margin-block: 0 !important;
}
[data-chat-mode="conversation"] .mari-messages-scroll > [data-mari-part="message"] {
  padding-block: 1px;
}
[data-chat-mode="conversation"] {
  --mari-focus-frame-outset: 0px;
}
[data-chat-mode="conversation"] [data-mari-part="composer"] {
  width: min(100% - 2rem, 60rem);
  margin-inline: auto;
}

/* ---------- Life: slow steam drifting up the hall, gas lamps breathing at night ---------- */
:root {
  --mari-ambient: url("theme:steam-banks.webp") 0 100% / 1600px auto repeat-x;
  --mari-ambient-opacity: 0.32;
  --mari-ambient-placement: behind-cards;
  --mari-ambient-animation: cp-steam-drift 90s linear infinite;
}
:root[data-theme="dark"] {
  --mari-ambient: url("theme:steam-banks.webp") 0 100% / 1600px auto repeat-x;
  --mari-ambient-opacity: 0.2;
}
@keyframes cp-steam-drift {
  0% { background-position: 0 104%; }
  50% { background-position: -800px 98%; }
  100% { background-position: -1600px 104%; }
}
/* gaslight: two warm haloes in the side galleries that breathe slowly */
:root[data-theme="dark"] [data-mari-part="ambient"]::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(14rem 18rem at 4% 52%, rgba(255, 186, 90, 0.22), transparent 70%),
    radial-gradient(14rem 18rem at 96% 46%, rgba(255, 186, 90, 0.22), transparent 70%);
  animation: cp-gas 5.5s ease-in-out infinite;
  pointer-events: none;
}
@keyframes cp-gas {
  0%, 100% { opacity: 0.75; }
  22% { opacity: 1; }
  30% { opacity: 0.82; }
  55% { opacity: 0.95; }
  70% { opacity: 0.7; }
}
/* real weather replaces the house steam, except fog, which becomes billowing steam at mid height */
:root[data-mari-weather]:not([data-mari-weather="clear"], [data-mari-weather="cloudy"], [data-mari-weather="fog"]) {
  --mari-ambient: none;
}
:root[data-mari-weather="fog"] {
  --mari-ambient: url("theme:steam-banks.webp") 0 62% / 1900px auto repeat-x, url("theme:steam-banks.webp") 700px 100% / 1500px auto repeat-x;
  --mari-ambient-opacity: 0.6;
  --mari-ambient-animation: cp-steam-billow 70s linear infinite;
  --mari-weather-tint-strength: 0.8;
}
@keyframes cp-steam-billow {
  0% { background-position: 0 64%, 700px 100%; }
  50% { background-position: -950px 58%, 1450px 98%; }
  100% { background-position: -1900px 64%, 2200px 100%; }
}
:root[data-theme="dark"][data-mari-weather="storm"],
:root[data-theme="dark"][data-mari-weather="rain"] {
  --mari-app-backdrop: url("theme:backdrop-storm-night.webp");
  --mari-app-backdrop-layers: url("theme:backdrop-storm-night.webp") center / cover no-repeat, var(--background);
  --mari-weather-tint-strength: 0.3;
}
@media (max-aspect-ratio: 4/5) {
  :root[data-theme="dark"][data-mari-weather="storm"],
  :root[data-theme="dark"][data-mari-weather="rain"] {
    --mari-app-backdrop-layers: url("theme:phone-night.webp") center / cover no-repeat, var(--background);
  }
}

/* at night every card surface keeps dark ink on gaslit stock */
:root[data-theme="dark"] :is([data-mari-part="home-widget"], [data-component="GlobalOmnibar.Panel"], [role="dialog"]:not([data-chat-help-overlay]), [data-game-narration], [data-mari-part="composer"] .mari-chat-input-box, [data-chat-mode="conversation"] .mari-messages-scroll > *) {
  --foreground: var(--cp-ink);
  --card-foreground: var(--cp-ink);
  --popover-foreground: var(--cp-ink);
  --muted-foreground: var(--cp-ink-soft);
  --marinara-chat-chrome-panel-title: var(--cp-ink);
  --marinara-chat-chrome-panel-muted: var(--cp-ink-soft);
  --marinara-chat-chrome-text: var(--cp-ink);
  --mari-chrome-muted: var(--cp-ink-soft);
  --ov-text: var(--cp-ink);
  --ov-muted: var(--cp-ink-soft);
  --ov-dim: var(--cp-ink-soft);
  --ov-line: var(--cp-rule);
  --border: var(--cp-rule);
  --secondary: color-mix(in srgb, var(--cp-card-solid) 85%, #8a6526);
  --muted: color-mix(in srgb, var(--cp-card-solid) 88%, #8a6526);
  --accent: color-mix(in srgb, var(--cp-card-solid) 80%, #8a6526);
  --accent-foreground: var(--cp-ink);
  --ov-hover: color-mix(in srgb, var(--cp-card-solid) 85%, #8a6526);
  --primary: #6b4a14;
  --primary-foreground: #fff6df;
  --mari-chrome-accent: #6b4a14;
  --mari-home-widget-glow: transparent;
  color: var(--cp-ink);
}
:root[data-theme="dark"] [role="dialog"]:not([data-chat-help-overlay]),
:root[data-theme="dark"] [data-component="GlobalOmnibar.Panel"] {
  background: var(--cp-card) !important;
}
[data-mari-part="chat-header"] .rounded-full,
[data-mari-part="chat-header"] [class*="rounded"] {
  border-radius: 1px !important;
}
:root[data-theme="dark"] [data-mari-part="chat-header"] > * > *:has(> img),
[data-mari-part="chat-header"] button:has(img) {
  background: var(--cp-card-solid) !important;
  color: var(--cp-ink) !important;
  border: 1px solid var(--cp-rule) !important;
}
[data-game-narration] button:not([class*="game-combat"]),
.ov-gpane button {
  color: var(--cp-ink) !important;
  border-color: var(--cp-rule) !important;
}
[data-game-narration] .anim-text-flicker {
  color: #9a3412 !important;
}

/* =====================================================================
   ROUND 3
   ===================================================================== */

/* ---------- night cards: ivory stock glowing under a gas lamp, edges falling into shadow ---------- */
:root[data-theme="dark"] {
  --cp-card:
    radial-gradient(ellipse 78% 72% at 50% 40%, rgba(255, 248, 228, 0.7), rgba(255, 240, 206, 0.32) 55%, rgba(255, 236, 196, 0) 82%),
    radial-gradient(ellipse 125% 115% at 50% 42%, rgba(70, 42, 12, 0) 52%, rgba(70, 42, 12, 0.34) 100%),
    #d8c69e url("theme:card-night.webp") 0 0 / 256px;
  --cp-card-solid: #e0d0aa;
  --cp-manila:
    radial-gradient(ellipse 80% 75% at 55% 40%, rgba(255, 244, 214, 0.5), rgba(255, 236, 196, 0) 80%),
    radial-gradient(ellipse 125% 115% at 50% 42%, rgba(70, 42, 12, 0) 52%, rgba(70, 42, 12, 0.3) 100%),
    #ccb88c url("theme:manila-night.webp") 0 0 / 256px;
  --mari-pinned-speaker-bg: #e0d0aa;
}

/* ---------- the clip: smaller, biting the card's own top edge just right of the rail ---------- */
[data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body::after {
  left: 20px;
  top: -22px;
  width: 40px;
  height: 40px;
}

/* ---------- phone: one card per message, a clip on every output card ---------- */
@media (max-width: 767px) {
  [data-chat-mode="roleplay"] .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    row-gap: 0;
    align-content: start;
  }
  /* your cards hug their text on the right; the plate and the body share one width */
  [data-chat-mode="roleplay"] .mari-message-user .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) {
    grid-template-columns: minmax(0, 1fr) fit-content(100%);
  }
  [data-chat-mode="roleplay"] .mari-message-user .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"],
  [data-chat-mode="roleplay"] .mari-message-user .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) > .mari-rp-bubble {
    grid-column: 2;
    justify-self: stretch;
    width: auto;
  }
  [data-chat-mode="roleplay"] .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
    border: 1px solid var(--cp-rule);
    border-bottom: 0;
    margin: 0;
    padding: 0.55rem 0.8rem 0.2rem;
    min-width: 0;
  }
  [data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
    background: var(--cp-card-solid);
  }
  /* output cards: the stock is painted once across plate and body, so there is no seam */
  [data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) {
    background: var(--cp-card);
    background-origin: content-box;
    background-clip: content-box;
  }
  [data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
    background: transparent;
  }
  [data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) > .mari-rp-bubble {
    background: transparent;
    box-shadow: none;
    border-top: 0 !important;
  }
  [data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) {
  }
  [data-chat-mode="roleplay"] .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) > .mari-rp-bubble {
    box-shadow: 0 10px 12px -10px rgba(0, 0, 0, 0.55) !important;
  }
  /* your cards: plate and body are one manila card, punched below the plate */
  [data-chat-mode="roleplay"] .mari-message-user .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"],
  :root[data-theme="dark"] [data-chat-mode="roleplay"] .mari-message-user .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
    background: var(--cp-manila);
    background-size: auto, auto, 256px;
    justify-content: flex-start;
  }
  :root[data-theme="light"] [data-chat-mode="roleplay"] .mari-message-user .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
    background: var(--cp-manila);
  }
  [data-chat-mode="roleplay"] .mari-message-user .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"]) > .mari-rp-bubble {
    padding-top: 8px;
    padding-bottom: 8px;
  }
  [data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body:has(> [data-mari-part="header"][data-placement="outside"])::after {
    display: none;
  }
  [data-chat-mode="roleplay"] .mari-message-assistant .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"]::after {
    content: "";
    position: absolute;
    left: -16px;
    top: -15px;
    width: 30px;
    height: 30px;
    background: url("theme:clip.png") center / contain no-repeat;
    filter: drop-shadow(1px 2px 1px rgba(0, 0, 0, 0.4));
    pointer-events: none;
    z-index: 5;
  }
  /* the carriage swallows the reply: lines fade out before they reach the roller */
  [data-chat-mode="roleplay"] .mari-messages-scroll {
    -webkit-mask-image: linear-gradient(#000 calc(100% - 96px - 1.25rem), rgba(0, 0, 0, 0.25) calc(100% - 96px - 0.5rem), transparent calc(100% - 96px));
    mask-image: linear-gradient(#000 calc(100% - 96px - 1.25rem), rgba(0, 0, 0, 0.25) calc(100% - 96px - 0.5rem), transparent calc(100% - 96px));
  }
}

/* ---------- square everything that was still rounded ---------- */
.mari-chrome-segmented,
.mari-chrome-segmented > *,
.mari-chrome-field,
.mari-chrome-sort-field,
[data-component="GlobalOmnibar.Results"] li,
[data-component="GlobalOmnibar.Results"] li > button,
[data-component="GlobalOmnibar.Panel"] button,
.ov-settings [class*="rounded"],
[data-mari-part="composer"] [class*="rounded"],
[class*="ov-home"] [class*="rounded"] {
  border-radius: 1px !important;
}

/* ---------- native selects get the same brass-bracketed plate as the custom ones ---------- */
.ov-settings select,
[data-component="ChatSidebar"] select {
  appearance: none;
  -webkit-appearance: none;
  background:
    linear-gradient(45deg, transparent 50%, currentColor 50%) right 13px center / 5px 5px no-repeat,
    linear-gradient(135deg, currentColor 50%, transparent 50%) right 8px center / 5px 5px no-repeat,
    color-mix(in srgb, var(--cp-card-solid) 82%, #8a6526) !important;
  color: var(--cp-ink) !important;
  border: 1px solid var(--cp-rule) !important;
  border-radius: 1px !important;
  padding-right: 1.75rem !important;
  padding-left: 0.7rem !important;
  min-height: 2.25rem;
}
[data-component="ChatSidebar"] select {
  background: var(--sidebar) !important;
  color: var(--sidebar-foreground) !important;
  border-color: var(--border) !important;
}

/* ---------- Settings: the section description reads in ink on its own line ---------- */
.ov-settings__sections section > div:first-child > div:not([class*="shrink"]) {
  display: block;
}
.ov-settings__sections section > div:first-child [class*="leading-relaxed"] {
  display: block;
  margin-top: 0.4rem;
  font-size: 0.875rem !important;
  color: var(--cp-ink-soft) !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  -webkit-line-clamp: unset !important;
}

/* ---------- Ctrl+K: section titles in label holders, continue cards wide enough for names ---------- */
[data-component="GlobalOmnibar.Results"] section h3 {
  display: inline-block;
  padding: 0 0.4rem;
  border-style: solid;
  border-width: 5px 14px;
  border-image: url("theme:label-holder.png") 9 28 10 28 fill / 5px 14px stretch;
  color: #2b2118 !important;
  font-family: var(--mari-font-heading);
  font-variant: small-caps;
  text-transform: none;
  letter-spacing: 0.08em;
  font-size: 0.85rem !important;
}
[data-component="GlobalOmnibar.Results"] section h3 + span {
  color: var(--cp-ink-soft) !important;
  font-size: 0.85rem;
}
@media (min-width: 640px) {
  [data-component="GlobalOmnibar.Results"] ul[class*="sm:grid-cols-3"] {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
}
[data-component="GlobalOmnibar.Results"] ul[class*="grid-cols-3"] li {
  border: 1px solid var(--cp-rule) !important;
  background: color-mix(in srgb, var(--cp-card-solid) 88%, #8a6526) !important;
}
[data-component="GlobalOmnibar.Results"] ul[class*="grid-cols-3"] li .truncate,
[data-component="GlobalOmnibar.Results"] ul[class*="grid-cols-3"] li [class*="truncate"] {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
}

/* ---------- Home hero: every mode plate on one iron bar under the greeting, clear of the engraving ---------- */
@media (min-width: 768px) and (min-aspect-ratio: 4/5) {
  .mari-home-hero {
    display: grid !important;
    grid-template-columns: max-content max-content 1fr;
    grid-template-rows: auto auto 1fr;
    justify-items: start;
    align-items: center;
    column-gap: 0 !important;
    row-gap: 1.1rem !important;
    background-size: auto 88%;
    background-position: right 0.5rem bottom 0;
  }
  .mari-home-hero > div:has(h1) {
    grid-column: 1 / -1;
    grid-row: 1;
  }
  .mari-home-hero > .mari-seasonal-home {
    grid-area: 1 / 1 / -1 / -1;
  }
  .mari-home-hero > .ov-home-modes,
  .mari-home-hero > .ov-home-hero-actions {
    position: static !important;
    inset: auto !important;
    transform: none !important;
    grid-row: 2;
    margin: 0 !important;
    display: flex;
    flex-wrap: nowrap;
    gap: 0.4rem;
    padding: 0.4rem 0.45rem;
    background: linear-gradient(180deg, #2a313c, #151a22);
    border-block: 1px solid #8a6526;
    box-shadow: 0 4px 10px -4px rgba(0, 0, 0, 0.6);
  }
  .mari-home-hero > .ov-home-modes {
    grid-column: 1;
    border-left: 1px solid #8a6526;
    padding-right: 0.2rem;
  }
  .mari-home-hero > .ov-home-hero-actions {
    grid-column: 2;
    border-right: 1px solid #8a6526;
    padding-left: 0.2rem;
  }
}
.ov-home-hero-actions button {
  background-image:
    radial-gradient(circle at 6px 50%, #f6de96 0 1px, #a5802f 1.6px 2.4px, transparent 2.9px),
    radial-gradient(circle at calc(100% - 6px) 50%, #f6de96 0 1px, #a5802f 1.6px 2.4px, transparent 2.9px) !important;
  padding-inline: 0.95rem !important;
  border-radius: 1px !important;
}

/* ---------- stragglers: the update toast is a telegram slip, Generate a riveted plate ---------- */
[data-sonner-toast] {
  background: var(--cp-card) !important;
  color: var(--cp-ink) !important;
  border: 1px solid var(--cp-rule) !important;
  border-radius: 1px !important;
  --normal-text: var(--cp-ink);
}
[data-sonner-toast] button {
  border-radius: 1px !important;
  background: linear-gradient(180deg, #e3c378, #b08a3a) !important;
  color: #2b2118 !important;
  border: 1px solid #6e4f1c !important;
}
[data-tour="game-map"] button {
  border-radius: 1px !important;
  background: color-mix(in srgb, var(--cp-card-solid) 80%, #8a6526) !important;
  color: var(--cp-ink) !important;
  border: 1px solid var(--cp-rule) !important;
}

/* ---------- the chats sidebar is a card catalogue: oak drawer fronts with a brass pull; the open chat is pulled out ---------- */
[data-chat-row] {
  border-radius: 1px !important;
  margin-block: 4px;
  padding-right: 46px !important;
  background:
    url("theme:drawer-pull.png") right 7px center / 34px auto no-repeat,
    repeating-linear-gradient(178deg, rgba(90, 52, 18, 0) 0 5px, rgba(90, 52, 18, 0.07) 5px 6px, rgba(90, 52, 18, 0) 6px 11px),
    linear-gradient(180deg, #e2c799, #d2b17b);
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 220, 0.6),
    inset 0 -2px 0 rgba(92, 56, 20, 0.35),
    inset 0 0 0 1px #8a6526,
    0 1px 0 rgba(255, 244, 220, 0.5);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  --mari-chrome-text: #2b2118;
  --mari-chrome-muted: #4a3418;
  color: #2b2118;
}
[data-chat-row] .mari-chrome-text-strong,
[data-chat-row] span {
  color: #2b2118;
}
:root[data-theme="dark"] [data-chat-row] {
  background:
    url("theme:drawer-pull.png") right 7px center / 34px auto no-repeat,
    repeating-linear-gradient(178deg, rgba(0, 0, 0, 0) 0 5px, rgba(0, 0, 0, 0.12) 5px 6px, rgba(0, 0, 0, 0) 6px 11px),
    linear-gradient(180deg, #4a3220, #35231585);
  background-color: #2c1d12;
  box-shadow:
    inset 0 1px 0 rgba(255, 210, 150, 0.18),
    inset 0 -2px 0 rgba(0, 0, 0, 0.45),
    inset 0 0 0 1px rgba(201, 160, 74, 0.55),
    0 1px 0 rgba(0, 0, 0, 0.5);
  --mari-chrome-text: #f3e6c8;
  --mari-chrome-muted: #d8c39a;
  color: #f3e6c8;
}
:root[data-theme="dark"] [data-chat-row] .mari-chrome-text-strong,
:root[data-theme="dark"] [data-chat-row] span {
  color: #f3e6c8;
}
:root[data-theme] [data-chat-row][data-selected="true"] {
  background:
    url("theme:drawer-pull.png") right 7px center / 34px auto no-repeat,
    var(--cp-card);
  transform: translateX(6px);
  box-shadow:
    inset 0 0 0 1px #8a6526,
    -6px 0 0 -1px #5c4016,
    0 6px 10px -4px rgba(0, 0, 0, 0.55);
}
:root[data-theme] [data-chat-row][data-selected="true"] .mari-chrome-text-strong,
:root[data-theme] [data-chat-row][data-selected="true"] span {
  color: var(--cp-ink);
}
@media (prefers-reduced-motion: reduce) {
  [data-chat-row] { transition: none; }
}

/* =====================================================================
   ROUND 4
   ===================================================================== */

/* ---------- night stock: one smooth radial of gaslight over the whole card ---------- */
:root[data-theme="dark"] {
  --cp-glow: radial-gradient(farthest-corner at 50% 42%, rgba(255, 247, 224, 0.62) 0%, rgba(255, 240, 206, 0.3) 38%, rgba(255, 236, 196, 0) 62%, rgba(70, 42, 12, 0.18) 82%, rgba(70, 42, 12, 0.34) 100%);
  --cp-card: var(--cp-glow), #d8c69e url("theme:card-night.webp") 0 0 / 256px;
  --cp-card-solid: #e3d2ab;
  --cp-manila: var(--cp-glow), #ccb88c url("theme:manila-night.webp") 0 0 / 256px;
  --mari-pinned-speaker-bg: #e3d2ab;
}
/* input cards: every layer is laid out on the same box, so the glow cannot stop at a tile edge */
[data-chat-mode="roleplay"] .mari-rp-bubble--user {
  background:
    var(--cp-holes) 4px 0 / 34px 80px,
    linear-gradient(var(--cp-rule), var(--cp-rule)) 42px 0 / 1px 100%,
    #ecdfbe url("theme:manila-day.webp") 0 0 / 256px;
  background-repeat: no-repeat round, no-repeat, repeat;
  background-origin: padding-box, border-box, border-box;
  background-clip: border-box;
}
:root[data-theme="dark"] [data-chat-mode="roleplay"] .mari-rp-bubble--user {
  background:
    var(--cp-holes) 4px 0 / 34px 80px,
    linear-gradient(var(--cp-rule), var(--cp-rule)) 42px 0 / 1px 100%,
    var(--cp-glow) 0 0 / 100% 100%,
    #ccb88c url("theme:manila-night.webp") 0 0 / 256px;
  background-repeat: no-repeat round, no-repeat, no-repeat, repeat;
  background-origin: padding-box, border-box, border-box, border-box;
  background-clip: border-box;
}
/* the plate band only paints while the name plate is actually stuck over a long reply */
@supports (container-type: scroll-state) {
  :root[data-mari-pinned-speaker] [data-chat-mode="roleplay"] .mari-rp-bubble .ov-rpmsg__head {
    container-type: scroll-state;
    background: transparent;
  }
  :root[data-mari-pinned-speaker] [data-chat-mode="roleplay"] .mari-rp-bubble .ov-rpmsg__head::after {
    opacity: 0;
  }
  @container scroll-state(stuck: top) {
    :root[data-mari-pinned-speaker] [data-chat-mode="roleplay"] .mari-rp-bubble .ov-rpmsg__head > * {
      position: relative;
    }
    :root[data-mari-pinned-speaker] [data-chat-mode="roleplay"] .mari-rp-bubble .ov-rpmsg__head > :first-child::before {
      content: "";
      position: absolute;
      left: -100vw;
      right: -100vw;
      top: -0.8rem;
      bottom: -2.9rem;
      z-index: -1;
      background: linear-gradient(var(--cp-card-solid) 80%, color-mix(in srgb, var(--cp-card-solid) 50%, transparent) 92%, transparent);
      pointer-events: none;
    }
  }
}

/* ---------- drawers: a smaller pull, the time on its own line, the title gets the drawer ---------- */
[data-chat-row] {
  min-height: 3.25rem;
  padding-right: 30px !important;
  padding-bottom: 14px !important;
  overflow: hidden;
  background-size: 21px auto, auto, auto !important;
}
:root[data-theme] [data-chat-row][data-selected="true"] {
  background-size: 21px auto, auto !important;
}
[data-chat-row] > span.tabular-nums {
  position: absolute;
  left: 53px;
  bottom: 3px;
  font-size: 0.8rem;
  line-height: 1.1;
  font-family: var(--cp-typed);
  letter-spacing: 0.04em;
}
[data-chat-row] > button.shrink-0:last-child {
  position: absolute;
  right: 30px;
  top: 4px;
}

/* ---------- the update toast: a telegram slip in ink, its close stud inside the slip ---------- */
[data-sonner-toast],
[data-sonner-toast] * {
  color: var(--cp-ink) !important;
  --normal-text: var(--cp-ink);
  --gray12: var(--cp-ink);
  --gray11: var(--cp-ink-soft);
}
[data-sonner-toast] [data-description] {
  color: var(--cp-ink-soft) !important;
  opacity: 1 !important;
}
[data-sonner-toast] {
  background: #f1e6cc url("theme:card-day.webp") 0 0 / 256px !important;
  box-shadow: 0 10px 20px -10px rgba(0, 0, 0, 0.7), inset 0 0 0 4px #f1e6cc, inset 0 0 0 5px var(--cp-rule) !important;
}
[data-sonner-toast] [data-close-button] {
  left: auto !important;
  right: 6px !important;
  top: 6px !important;
  transform: none !important;
  background: linear-gradient(180deg, #e3c378, #b08a3a) !important;
  border: 1px solid #6e4f1c !important;
  border-radius: 1px !important;
}
[data-sonner-toast] [data-button] {
  color: #2b2118 !important;
}

/* ---------- the Library sidebar: card stock with a label-holder heading and brass rules ---------- */
.ov-libnav {
  background: var(--cp-card) !important;
  box-shadow: inset 3px 0 0 -1px rgba(138, 101, 38, 0.8), inset 4px 0 0 -1px rgba(0, 0, 0, 0.25);
  --ov-text: var(--cp-ink);
  --ov-muted: var(--cp-ink-soft);
  --ov-dim: var(--cp-ink-soft);
  --ov-line: var(--cp-rule);
  --ov-hover: color-mix(in srgb, var(--cp-card-solid) 82%, #8a6526);
  --ov-active-bg: color-mix(in srgb, var(--cp-card-solid) 72%, #8a6526);
  --foreground: var(--cp-ink);
  --muted-foreground: var(--cp-ink-soft);
  --border: var(--cp-rule);
  --accent: color-mix(in srgb, var(--cp-card-solid) 80%, #8a6526);
  --accent-foreground: var(--cp-ink);
  --primary: #6b4a14;
  --mari-chrome-accent: #6b4a14;
  color: var(--cp-ink);
}
.ov-libnav .ov-libnav__title {
  justify-self: start;
  align-self: flex-start;
  width: auto;
  display: inline-block;
  padding: 0 0.5rem;
  margin: 0.2rem 0 0.4rem 0.2rem;
  border-style: solid;
  border-width: 5px 14px;
  border-image: url("theme:label-holder.png") 9 28 10 28 fill / 5px 14px stretch;
  color: #2b2118 !important;
  font-family: var(--mari-font-heading);
  font-variant: small-caps;
  font-style: normal;
  letter-spacing: 0.08em;
  font-size: 1.05rem !important;
  line-height: 1.5;
}
.ov-libnav__item,
.ov-libnav__item * {
  color: var(--cp-ink) !important;
}
.ov-libnav__item svg {
  color: #6b4a14 !important;
}
.ov-libnav__item {
  border-radius: 1px !important;
}
.ov-libnav__item[aria-current],
.ov-libnav__item.is-active,
.ov-libnav__item[data-active="true"] {
  background: color-mix(in srgb, var(--cp-card-solid) 70%, #8a6526) !important;
  box-shadow: inset 3px 0 0 #8a6526;
}
.ov-libnav__rule {
  height: 5px !important;
  background:
    radial-gradient(circle, #f6de96 0 1px, #a5802f 1.6px 2.4px, transparent 2.9px) center / 8px 5px no-repeat,
    linear-gradient(#8a6526, #8a6526) center / 100% 1px no-repeat !important;
}

/* =====================================================================
   FINAL POLISH
   ===================================================================== */
/* the survey card's Generate button: a full brass plate */
[data-tour="game-map"] button {
  opacity: 1 !important;
  background:
    radial-gradient(circle at 6px 50%, #fff1c4 0 1px, #6e4f1c 1.6px 2.4px, transparent 2.9px),
    radial-gradient(circle at calc(100% - 6px) 50%, #fff1c4 0 1px, #6e4f1c 1.6px 2.4px, transparent 2.9px),
    linear-gradient(180deg, #f6de96, #c9a04a 45%, #9a7428) !important;
  color: #2b2118 !important;
  border: 1px solid #5c4016 !important;
  box-shadow: inset 0 1px 0 rgba(255, 250, 225, 0.7), 0 2px 3px -1px rgba(0, 0, 0, 0.5) !important;
  padding-inline: 1rem !important;
  font-weight: 700;
}
[data-tour="game-map"] button * {
  color: #2b2118 !important;
}
/* the swipe counter sits on a small riveted iron plate */
.ov-rpf__swipes {
  display: inline-flex;
  align-items: center;
  padding: 1px 12px;
  background:
    radial-gradient(circle at 5px 50%, #f6de96 0 1px, #a5802f 1.6px 2.2px, transparent 2.7px),
    radial-gradient(circle at calc(100% - 5px) 50%, #f6de96 0 1px, #a5802f 1.6px 2.2px, transparent 2.7px),
    linear-gradient(180deg, #2f3744, #161b23);
  border: 1px solid #8a6526;
  border-radius: 1px;
  box-shadow: 0 2px 4px -1px rgba(0, 0, 0, 0.5);
  --ov-text: #f3e6c8;
  color: #f3e6c8;
}
.ov-rpf__swipes button,
.ov-rpf__swipes button * {
  color: #f3e6c8 !important;
  border-radius: 1px !important;
}
/* Recent chats: the chat type sits in a small label holder */
.ov-recent__mode {
  border-style: solid !important;
  border-width: 4px 11px !important;
  border-image: url("theme:label-holder.png") 9 28 10 28 fill / 4px 11px stretch !important;
  border-radius: 0 !important;
  background: none !important;
  color: #2b2118 !important;
  padding: 0 0.3rem !important;
  font-family: var(--mari-font-heading);
  font-variant: small-caps;
  letter-spacing: 0.04em;
}
/* the composer's quick-switch chevron gets a plate like its neighbours */
[data-mari-part="composer"] button[title="Quick Switcher"] {
  background: color-mix(in srgb, var(--cp-card-solid) 80%, #8a6526) !important;
  border: 1px solid var(--cp-rule) !important;
  border-radius: 1px !important;
  color: var(--cp-ink) !important;
  width: 2.25rem !important;
  height: 2.25rem !important;
}
